def render_invoice(lines):
    """The whole invoice as one string: every line as render_line gives it, then TOTAL.

    Each entry may be a line dict or a raw row string, which parse_line converts.
    """
    body = "\n".join(render_line(parse_line(l) if isinstance(l, str) else l) for l in lines)
    return f"{body}\nTOTAL\t{invoice_total(lines):.2f}"

